 public async void RunRefinementChecks(){int checks=0;string phase="setup",report=Path.Combine(baseDir,"../test-output/refinements.txt");Action<bool,string> check=(ok,message)=>{checks++;if(!ok)throw new Exception(message);};File.WriteAllText(report,"RUNNING");try{
