  CaptureDocumentation();check(Diagnostics.ErrorCount==0,"Native UI errors logged");File.WriteAllText(report,"PASS: "+checks+" targeted checks. 500 stationary dodge positions all defeated within "+longest.ToString("0.0")+"s; footprints, variety, proven crate deadlocks and automatic restart, pour/deselection/ramp, learning selection, tracing preservation/comparison, zoom/fit, pen modes, live paper preview, isolated layered editor save/cancel, and native renders in all five themes and both languages. No desktop interaction.");
